// Policy boundaries are unit fixtures; browser proofs load views generated by normal route controls.
import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {M01Simulation} from '../src/game/m01-simulation.js';
import {M01HudPresenter} from '../src/ui/m01-hud.js';
import {corridorGuidance} from '../src/ui/m01-corridor-guidance.js';
function view(name='medic-carrying'){
 const s=new M01Simulation();s.restoreSnapshot(JSON.parse(readFileSync(new URL(`./fixtures/m01-sp08-${name}.json`,import.meta.url))));s.drainEvents();return s;
}
const guidance=s=>corridorGuidance(s,s.objectiveMarker);
test('the real entry keeps its actual 9/12 count and identifies the post as the player role',()=>{
 const s=view('entry'),status=s.mission.status,g=guidance(s);
 assert.match(status,/9 de 12/);assert.equal(g.status,`Mantenha o posto · ${status}`);assert.equal(g.marker,null);assert.equal(s.mission.status,status);
});
test('Dudek is an observation target while the real patient is on his shoulder',()=>{
 const s=view(),g=guidance(s),a=s.actor('leon_dudek');assert.equal(s.actor('jozef_bak').carriedBy,a.id);
 assert.match(g.status,/^Mantenha o posto ·/);assert.equal(g.marker.label,'Dudek com Bąk · observe a retirada');assert.equal(g.marker.x,a.x);assert.equal(g.marker.y,a.y);assert.equal(g.marker.z,a.z);
 assert.equal(g.marker.distance,Math.hypot(a.x-s.player.x,a.z-s.player.z));assert.ok(Math.abs(g.marker.bearing)>3,'the real companion is behind the view; observing does not mean following him');
});
test('the genuine walk away from the post points back to the actual completion point',()=>{
 const s=view('outside-post'),post=s.world.point('firing_point'),g=guidance(s);
 assert.match(g.status,/^Regresse ao posto ·/);assert.match(g.marker.label,/Posto de disparo/);assert.deepEqual([g.marker.x,g.marker.y,g.marker.z],[post.x,post.y,post.z]);
 assert.equal(g.marker.distance,Math.hypot(post.x-s.player.x,post.z-s.player.z));
});
test('the position boundary is the mission completion radius, including its exact edge',()=>{
 const s=view(),post=s.world.point('firing_point'),r=s.definition.objectives.find(o=>o.id==='obj_m01_leave_bridge').completion.radiusM;
 Object.assign(s.player,{x:post.x+r,z:post.z});assert.match(guidance(s).status,/^Mantenha/);
 s.player.x+=.001;assert.match(guidance(s).status,/^Regresse/);
});
test('relative direction follows the actual player view, without rotating or moving the player',()=>{
 const s=view('outside-post'),post=s.world.point('firing_point'),p=s.player;p.angle=Math.atan2(post.z-p.z,post.x-p.x);
 assert.ok(Math.abs(guidance(s).marker.bearing)<1e-12);p.angle+=Math.PI/2;assert.ok(Math.abs(guidance(s).marker.bearing+Math.PI/2)<1e-12);
});
test('a player carrying Bąk keeps the rescue destination and its original status priority',()=>{
 const s=view();s.player.carrying='jozef_bak';assert.equal(guidance(s),null);
});
test('an optional unclaimed rescue keeps the original offer and target',()=>{
 const s=view('outside-post');s.objectives.obj_m01_rescue_bak.state='active';s.actor('jozef_bak').carriedBy=null;assert.equal(guidance(s),null);
});
test('all-clear is actual B4 readiness: preserve its confirmation and reduce the marker',()=>{
 const s=view('all-clear');assert.equal(s.readiness('evt_m01_west_demolition'),true);const g=guidance(s);
 assert.equal(g.status,s.mission.status);assert.match(g.status,/Todos fora da ponte/);assert.equal(g.marker,null);
});
test('the real west demolition ends the corridor context and cannot leave an outdated order',()=>{
 const s=view('west-blast');assert.equal(s.objectives.obj_m01_hold_corridor.state,'done');assert.equal(guidance(s),null);
});
test('cinema, death, another objective and missing contracts never invent a corridor order',()=>{
 for(const change of [s=>{s.scene={id:'cs_m01_order'};},s=>{s.player.alive=false;},s=>{s.objectives.obj_m01_hold_corridor.state='done';},s=>{s.world.point=()=>{throw Error('missing map point');};},s=>{s.definition={objectives:[]};}]){
  const s=view();change(s);assert.equal(guidance(s),null);
 }
});
test('repeated presentation is draw-free and cannot write gameplay state, events or saved data',()=>{
 const s=view(),before=s.snapshot(),rng=s.rng.state;
 for(let i=0;i<300;i++)guidance(s);
 assert.deepEqual(s.snapshot(),before);assert.equal(s.rng.state,rng);assert.deepEqual(s.drainEvents(),[]);
 const restored=new M01Simulation();restored.restoreSnapshot(before);assert.deepEqual(guidance(restored),guidance(s));
});
test('the existing marker memo freezes corridor context between ticks and is cleared by restore/menu',()=>{
 const s=view(),h=new M01HudPresenter({}),first=h.markerFor(s),status=h.markerMemo.corridorStatus;
 for(let i=0;i<300;i++)assert.strictEqual(h.markerFor(s),first);assert.equal(h.markerMemo.corridorStatus,status);
 const outside=view('outside-post');h.reset('restore',outside.clock);assert.match(h.markerFor(outside).label,/Posto de disparo/);assert.match(h.markerMemo.corridorStatus,/^Regresse/);
 h.clear();assert.equal(h.markerMemo,null);h.markerFor(new M01Simulation());assert.equal(h.markerMemo.corridorStatus,undefined);
});
